initial_action.action_postfix:
// Initialize Nevada Commerce Tax
result.nv_qualifies_for_exemption false xdef
result.nv_commerce_tax 0.0 xdef

// Initialize sitused revenue
result.nv_sitused_revenue 0.0 xdef
result.nv_gross_revenue 0.0 xdef

action_details.action_postfix:
// No apportionment - assume 100% Nevada
result.nv_sitused_revenue result.total_revenue xdef
result.nv_gross_revenue result.total_revenue xdef

// No nexus - no revenue sitused to Nevada
result.nv_sitused_revenue 0.0 xdef
result.nv_gross_revenue 0.0 xdef

initial_action.action_postfix:
// Initialize Commerce Tax
result.nv_taxable_revenue 0.0 xdef
result.nv_commerce_tax 0.0 xdef

action_details.action_postfix:
// Calculate taxable revenue (gross revenue minus $4M threshold)
result.nv_gross_revenue result.nv_commerce_tax_threshold sub
0.0 max
/result.nv_taxable_revenue xdef

// Calculate Commerce Tax on taxable revenue
result.nv_taxable_revenue result.nv_commerce_tax_rate mul
/result.nv_commerce_tax xdef

// Apply credits
result.nv_commerce_tax result.state_credits sub
0.0 max
/result.nv_commerce_tax xdef

// Commerce Tax is reported as "state tax"
result.state_tax result.nv_commerce_tax xdef

// Calculate refund or amount owed
result.state_payments result.state_tax sub
/result.state_refund_or_owed xdef
